Method.Implementation:
#dim tSC As %Status=$$$OK $$$TRACE("Inside Method ProcessHttpsRequest") Set httprequest=##class(%Net.HttpRequest).%New() Set mdmPatientUrl = ..Adapter.URL, mdmPatientUrl=$E(mdmPatientUrl) $$$TRACE("MDM patient URL: "_mdmPatientUrl) set httprequest.Username = ##class(Ens.Config.Credentials).GetValue(..Adapter.Credentials, "Username") set httprequest.Password = ##class(Ens.Config.Credentials).GetValue(..Adapter.Credentials, "Password") Set httprequest.ContentType="application/json; charset=utf-8" Do httprequest.EntityBody.Write() do httprequest.EntityBody.CopyFrom(pRequest.Stream)
Set pResponse=##class(EnsLib.HTTP.GenericMessage).%New() try{ $$$TRACE("Calling Patient MDM Service.....") set postStatus = httprequest.Post(mdmPatientUrl)
set postStatusTxt = $SYSTEM.Status.GetOneErrorText(postStatus) $$$TRACE("postStatusTxt--> "_postStatusTxt) set response=httprequest.HttpResponse $$$TRACE("StatusLine: "_response.StatusLine) set statusLine = response.StatusLine set statusCode = "" set statusDesc = "" if (statusLine'=""){ set statusCode=$piece(statusLine," ",2) set statusDesc=$piece(statusLine," ",3) } $$$TRACE("StatusCode: "_statusCode) $$$TRACE("StatusDesc: "_statusDesc) if (postStatus =1){ set respData = httprequest.HttpResponse.Data.Read() $$$TRACE("RESP DATA ???? "_respData) }else{ set errTxt = " RETRY. Verato service post request failed." $$$TRACE(" Post Failed.. " _ errTxt) set tSC=##class(IHC.ITF.ITFCOMMON.Utility).RetryCheckError("Out-InformaticaMdm-Json-Wsrc-PATIENT"," Response from Patient MDM Service Post Operation: "_respData) }
}catch e{ $$$TRACE(" Unknown Exception: " _ e) set errTxt = $System.Status.GetErrorText("Unknown Exception while calling Patient MDM service "_e) Set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Out-InformaticaMdm-Json-Wsrc-PATIENT",errTxt) }
quit tSC
